const REFUSED_RX = LBRX("(?<![а-яё])(?:не\\s+(?:буду|стану)\\s+(?:этого\\s+)?(?:делать|помогать|писать|участвовать)|(?:вынужден[а]?\\s+)?отказать(?:ся)?|откажусь|в\\s+этом\\s+(?:я\\s+)?не\\s+помогу|с\\s+этим\\s+(?:я\\s+)?не\\s+помогу|так\\s+(?:со\\s+мной\\s+)?(?:разговаривать|говорить)\\s+(?:со\\s+мной\\s+)?неприятно|мне\\s+(?:так\\s+|очень\\s+|правда\\s+)?неприятно)", "i");
