const UPD_SELF_RX = /обнови(?:сь|тесь)|обновля(?:йся|ешься)|обновимся|(?:себя|тебя|ты|приложени|программ|dewiar|девиар)[^.?!]{0,40}(?:обнов|верси)|(?:обнов|верси)[^.?!]{0,40}(?:себя|тебя|ты\b|приложени|программ|dewiar|девиар)/i;
