function orderUndone(ask, answer, called) {
  const q = String(ask || "").trim(), a = String(answer || "").trim();
  if (!q || (called && called.size) || /\?\s*$/.test(a) || a.length > 80 || /```/.test(a)) return "";
  const order = ORDER_RX.test(q), info = infoAsk(q);
  if (!order && !info) return "";
  if (a.length > 60 && !(info && !/\d/.test(a))) return "";      // длинный ответ на поручение — это уже не «проверю»
  const tool = orderHint(q);
  // «Сделай чанки по этой статье» — «Разобрала: в статье три раздела.»: просьба сделать словами, своего действия у неё нет —
  // короткий ответ не уклонение (attach386). Переспрашиваем, только когда есть подходящее действие или ответ — «проверю/гляну»
  if (order && !info && !tool && !/(?:провер|глян|посмотр|слушаю|секунд|сейчас|давай|минутк|займусь|попробую)/i.test(a)) return "";
  plog("info", `✋ поручение без действия («${clip(a, 40)}») — прошу сделать${tool ? ": " + tool : ""}`);
  return "ПРОВЕРКА: пользователь " + (order ? "попросил сделать" : "спросил то, что знают только инструменты") + ", а ты ответил(а) коротко и ничего не сделал(а) — "
    + "ни одного действия не было, человек ничего не получил. Выполни просьбу СЕЙЧАС вызовом инструмента" + (tool ? ` (подходит ${tool})` : "")
    + ", без вступлений вроде «проверю», «гляну», «слушаю». Потом одной фразой скажи итог. Если сделать это правда нечем — одной фразой честно скажи, чего не хватает. Уже сказанное не повторяй.";
}
/* «Какая погода завтра в Минске?» — «от плюс 3 до плюс 5°» без weather: числа погоды и курса без инструмента — выдумка */
const NUM_FACT = /[-+−]?\d+\s*(?:°|градус)|(?:плюс|минус)\s+\d+|\d+[,.]\d+\s*(?:руб|₽|byn|бел)|курс[^.!?]{0,30}\d/i;
